// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetAnalytics Scenario analytics
	// (GET /admin/analytics/{scenarioId})
	GetAnalytics(ctx context.Context, request GetAnalyticsRequestObject) (GetAnalyticsResponseObject, error)
	// GetAnalyticsReport Download analytics PDF report
	// (GET /admin/analytics/{scenarioId}/report)
	GetAnalyticsReport(ctx context.Context, request GetAnalyticsReportRequestObject) (GetAnalyticsReportResponseObject, error)
	// GenerateAnalyticsReport Generate analytics PDF report
	// (POST /admin/analytics/{scenarioId}/report)
	GenerateAnalyticsReport(ctx context.Context, request GenerateAnalyticsReportRequestObject) (GenerateAnalyticsReportResponseObject, error)
	// ListScenarios List scenarios
	// (GET /admin/scenarios)
	ListScenarios(ctx context.Context, request ListScenariosRequestObject) (ListScenariosResponseObject, error)
	// CreateScenario Create scenario
	// (POST /admin/scenarios)
	CreateScenario(ctx context.Context, request CreateScenarioRequestObject) (CreateScenarioResponseObject, error)
	// GetScenario Get scenario
	// (GET /admin/scenarios/{id})
	GetScenario(ctx context.Context, request GetScenarioRequestObject) (GetScenarioResponseObject, error)
	// UpdateScenario Update scenario
	// (PATCH /admin/scenarios/{id})
	UpdateScenario(ctx context.Context, request UpdateScenarioRequestObject) (UpdateScenarioResponseObject, error)
	// PublishScenario Publish scenario
	// (POST /admin/scenarios/{id}/publish)
	PublishScenario(ctx context.Context, request PublishScenarioRequestObject) (PublishScenarioResponseObject, error)
	// CreateStep Create step
	// (POST /admin/scenarios/{id}/steps)
	CreateStep(ctx context.Context, request CreateStepRequestObject) (CreateStepResponseObject, error)
	// ReorderSteps Reorder steps
	// (PUT /admin/scenarios/{id}/steps/order)
	ReorderSteps(ctx context.Context, request ReorderStepsRequestObject) (ReorderStepsResponseObject, error)
	// DeleteStep Delete step
	// (DELETE /admin/scenarios/{id}/steps/{stepId})
	DeleteStep(ctx context.Context, request DeleteStepRequestObject) (DeleteStepResponseObject, error)
	// UpdateStep Update step
	// (PATCH /admin/scenarios/{id}/steps/{stepId})
	UpdateStep(ctx context.Context, request UpdateStepRequestObject) (UpdateStepResponseObject, error)
	// UnpublishScenario Unpublish scenario
	// (POST /admin/scenarios/{id}/unpublish)
	UnpublishScenario(ctx context.Context, request UnpublishScenarioRequestObject) (UnpublishScenarioResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

